// Builds src/preload/ui-main.js: Drift's UI bridge + the extension toolbar element
// (<browser-action-list>) inlined so it can run in a sandboxed preload.
const fs = require('fs'); const path = require('path')
const root = path.join(__dirname, '..')
const ba = fs.readFileSync(require.resolve('electron-chrome-extensions/browser-action', { paths: [root] }), 'utf8')
const ui = fs.readFileSync(path.join(root, 'src/preload/ui.js'), 'utf8')
const out = `// GENERATED by scripts/bundle-preload.js — do not edit.
${ui}
;(() => {
  const module = { exports: {} }
  ;(function (module, exports) {
${ba}
  })(module, module.exports)
  module.exports.injectBrowserAction()
})()
`
fs.writeFileSync(path.join(root, 'src/preload/ui-main.js'), out)
console.log('wrote src/preload/ui-main.js')
